import{_ as t,c as o,b as l,o as a}from"./app-DyGkStdA.js";const n={};function r(i,e){return a(),o("div",null,e[0]||(e[0]=[l('<h2 id="blue-dart" tabindex="-1"><a class="header-anchor" href="#blue-dart"><span>Blue Dart</span></a></h2><p>Blue Dart is an Indian logistics company that provides courier delivery services. It has a business of ground transportation &amp; integrated air. Thus, it distributes time-sensitive packages to various destinations.</p><p>Now, Blue Dart is integrated with the very popular <a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multi-vendor Marketplace</a> App for Shopify. So, you can now allow sellers to fulfill orders via Blue Dart fulfillment &amp; courier delivery services. Additionally, allow sellers to generate shipping labels for fulfilled orders.</p><p>This feature of the Multivendor app will charge you a minimal amount of $10 per month over and above your current Multivendor plan.</p><p>BLUEDART SHIPPING FEATURE APP IS AVAILABLE <strong>ONLY FOR FULFILLMENT</strong>.</p><h3 id="points-to-be-noted" tabindex="-1"><a class="header-anchor" href="#points-to-be-noted"><span>Points to be Noted</span></a></h3><ul><li>Blue Dart shipping feature is available in all the three plans of the Multi-vendor Marketplace App.</li><li>It is necessary for admin to have an account on Blue Dart as these Blue Dart account details will help the admin to configure settings in the app.</li><li>Make the <strong>Contact Number, a mandatory field for the customers</strong> for checkout.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Screenshot-27.png" alt="Blue Dart"></p><p>Click the <strong>Enable</strong> Button.</p><h3 id="how-to-activate" tabindex="-1"><a class="header-anchor" href="#how-to-activate"><span>How to Activate</span></a></h3><p>To enable this feature within your app, all you need to do is to visit the “Featured Apps” section of the admin panel and activate it from there.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Home-Admin-1.png" alt="Feature App "></p><p>Once you click on “Feature Apps”, you will get the list of apps listing in this section. Now, you can scroll down to get the <strong>Blue Dart</strong> feature and click on the <strong>enable</strong> button.</p><p>In this way, you can enable the feature within your Multivendor App.</p><h3 id="workflow" tabindex="-1"><a class="header-anchor" href="#workflow"><span>WorkFlow</span></a></h3><h2 id="admin-end" tabindex="-1"><a class="header-anchor" href="#admin-end"><span>ADMIN END</span></a></h2><p>As soon as the admin enables this feature app, a new sub-menu gets added in the Configuration menu of the app i.e. Blue Dart Configuration. Now, the admin needs to have an account on <strong><a href="https://bluedart.com/" target="_blank" rel="noopener noreferrer">Blue Dart</a></strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Home-Admin.png" alt="Blue Dart"></p><p>Visiting the BlueDart Configuration section, the admin needs to configure all the details and do the settings accordingly. These details include the Licence Key, Customer Code, Origin Area Code, and Login ID.</p><p>Moreover, the admin will have the option to let the sellers <strong>generate Shipping labels automatically on order fulfillment</strong>. Also, the admin can set &quot;who will bear the shipping label cost&quot; whether Admin or Seller.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Bluedart-Configuration-Admin-1.png" alt="Details"></p><p>Once the admin configures the details from his/her admin panel, sellers immediately get the option to fulfill orders via Blue Dart on their respective seller panels.</p><h3 id="automatic-track-orders" tabindex="-1"><a class="header-anchor" href="#automatic-track-orders"><span>Automatic Track Orders</span></a></h3><p>You can now allow sellers to enter their tracking numbers and track orders.<br> Go to Multi-vendor Admin Panel&gt;&gt;Configuration&gt;&gt;Bluedart Configuration&gt;&gt;Configure details&gt;&gt;Save</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/01/7300b5aa-4036-4f72-9151-37be71189fb0-1200x584.png" alt="7300b5aa-4036-4f72-9151-37be71189fb0"></p><p>So, once the order is delivered to the customer, the tracking number gets updated for that order into the app. The sellers don&#39;t need to mark their orders as &quot;Delivered&quot; manually from their end.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/01/30116b0d-fd7f-4b79-ae10-fbdc6fd9e14a-1200x584.png" alt="30116b0d-fd7f-4b79-ae10-fbdc6fd9e14a"></p><p>Clicking the Track Order button, sellers can check the order status.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/01/download-5-1200x541.png" alt="download-5"></p><h2 id="seller-end" tabindex="-1"><a class="header-anchor" href="#seller-end"><span>SELLER END</span></a></h2><p>The Seller can configure the packet details from the Global Configuration section.<br> Seller Panel&gt;&gt;Configuration&gt;&gt;<strong>Shipping Configuartion</strong>&gt;&gt;Click the Global Configuration button&gt;&gt;Configure the shipping packet details.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Screenshot-23.png" alt="Shipping "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-3.png" alt="configuration"></p><p>Now, as soon as an order is placed, the seller will visit the order detail section to fulfill the order.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Order-Seller-•-Multivendor-MarketPlace.png" alt="Orders"></p><p>Visiting the Order detail section, click the <strong>Fulfill</strong> button to fulfill the order.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Order-Details-Seller-•-Multivendor-MarketPlace-5.png" alt="fulfill order"></p><p>Clicking the Fulfill button, the seller will get the option to select a method of fulfillment. The Seller needs to choose Blue Dart.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Screenshot1-1.png" alt="blue dart"></p><p>After that, the seller needs to <strong>choose a shipping method</strong> for the Blue Dart courier service. &quot;Make sure that the shipping method (to be selected) depends on the mode of payment selected by the customer at the time of checkout.&quot;<br> For Example:- Choose <strong>eTailCODAirInbound in case the</strong> customer&#39;s mode of payment is COD.</p><p>Also, select the pickup Date &amp; Time for the courier service and click the <strong>Agree and Fulfill</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Order-Details-Seller-•-Multivendor-MarketPlace-4.png" alt="fulfill order"></p><p>Now, proceed to generate the Shipping Label.</p><h3 id="generate-shipping-label" tabindex="-1"><a class="header-anchor" href="#generate-shipping-label"><span>Generate Shipping Label</span></a></h3><p>Clicking the Agree and Fulfill button, the seller can generate a shipping label for this order.</p><p><strong>Shipping Label Generated:-</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/10/Screenshot2.png" alt="shipping label"></p><p>Once generated, the seller can view the fulfillment details from the Order details section &amp; Print the shipping label in PDF format.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/01/download-6.png" alt="download-6"></p><h2 id="demo" tabindex="-1"><a class="header-anchor" href="#demo"><span>DEMO</span></a></h2><p>Link to check the demo of Multi-vendor Marketplace app for Shopify: <a href="https://multivendor-marketplace-5.myshopify.com" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com</a></p>',51)]))}const p=t(n,[["render",r]]),d=JSON.parse('{"path":"/classic/Featured-App/Shipping/BLUEDART.html","title":"BLUEDART SHIPPING","lang":"en-US","frontmatter":{"title":"BLUEDART SHIPPING","description":"BLUEDART SHIPPING","date":"2025-07-18T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":2,"title":"Blue Dart","slug":"blue-dart","link":"#blue-dart","children":[{"level":3,"title":"Points to be Noted","slug":"points-to-be-noted","link":"#points-to-be-noted","children":[]},{"level":3,"title":"How to Activate","slug":"how-to-activate","link":"#how-to-activate","children":[]},{"level":3,"title":"WorkFlow","slug":"workflow","link":"#workflow","children":[]}]},{"level":2,"title":"ADMIN END","slug":"admin-end","link":"#admin-end","children":[{"level":3,"title":"Automatic Track Orders","slug":"automatic-track-orders","link":"#automatic-track-orders","children":[]}]},{"level":2,"title":"SELLER END","slug":"seller-end","link":"#seller-end","children":[{"level":3,"title":"Generate Shipping Label","slug":"generate-shipping-label","link":"#generate-shipping-label","children":[]}]},{"level":2,"title":"DEMO","slug":"demo","link":"#demo","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"classic/Featured-App/Shipping/BLUEDART.md"}');export{p as comp,d as data};
